export function AiAction({
  label = "{{label}}",
  status = "{{status}}",
  accent = "{{accent}}",
  radius = {{radius}},
  reversible = {{reversible}},
}) {
  const badge = {
    suggested: { background: "transparent", color: accent, borderColor: accent },
    applied: { background: accent, color: "#FAF7F2", borderColor: accent },
    dismissed: { background: "transparent", color: "#24143066", borderColor: "#24143033", textDecoration: "line-through" },
  }[status] ?? {};
  return (
    <div style={{ maxWidth: 420, padding: "16px 18px", background: "#FAF7F2", color: "#241430",
      border: "1.5px solid #24143022", borderRadius: radius, boxSizing: "border-box", fontFamily: "system-ui, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span aria-hidden="true" style={{ color: accent, fontSize: 16, flexShrink: 0 }}>&#10022;</span>
        <p style={{ flex: 1, margin: 0, fontWeight: 600, fontSize: 14 }}>{label}</p>
        <span style={{ textTransform: "capitalize", fontSize: 11, fontWeight: 700, padding: "0.3em 0.7em",
          borderRadius: 999, border: "1.5px solid", boxSizing: "border-box", ...badge }}>{status}</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 12, flexWrap: "wrap" }}>
        <button type="button" style={{ font: "600 13px system-ui, sans-serif", padding: "7px 14px", borderRadius: 8,
          border: `1.5px solid ${accent}`, background: accent, color: "#FAF7F2", cursor: "pointer" }}>Run</button>
        <button type="button" disabled={!reversible} style={{ font: "600 13px system-ui, sans-serif", padding: "7px 14px",
          borderRadius: 8, border: `1.5px solid ${accent}`, background: "transparent", color: accent,
          cursor: reversible ? "pointer" : "not-allowed", opacity: reversible ? 1 : 0.4 }}>Undo</button>
        {reversible && <p style={{ margin: 0, fontSize: 12, color: "#24143099" }}>Undo available</p>}
      </div>
    </div>
  );
}
